// WorkspaceSearchResponse defines model for WorkspaceSearchResponse.
type WorkspaceSearchResponse struct {
	Chunks []WorkspaceSearchChunk `json:"chunks"`

	// FailedRepos Repos whose per-project vector search returned an error
	// during this request (e.g. corrupt collection on disk). The
	// rest of the workspace is still aggregated; surface this so
	// the operator knows the result set is incomplete.
	FailedRepos *[]WorkspaceSearchFailedRepo `json:"failed_repos,omitempty"`

	// PendingRepos Repos that belong to the workspace but weren't queryable
	// yet — clone or index hasn't completed (or the last attempt
	// failed). Their matches will appear once they reach
	// `status=indexed`. Empty if every repo is ready.
	PendingRepos *[]WorkspaceSearchPendingRepo `json:"pending_repos,omitempty"`

	// Projects Top projects ranked by `project_score`. Surfaces which repos
	// in the workspace the query is most relevant to, independent
	// of which individual chunks rank highest globally.
	Projects []WorkspaceSearchProject `json:"projects"`

	// StaleFtsRepos Repos that were indexed before the BM25 mirror
	// (`chunks_fts`) was added: they're queryable via dense
	// search but the sparse half of the hybrid is empty, which
	// collapses the algorithm to pure-dense fan-out for these
	// entries. Trigger a reindex on each to backfill the FTS
	// side. Empty once every workspace repo has been reindexed
	// under the new schema.
	StaleFtsRepos *[]WorkspaceSearchStaleFTSRepo `json:"stale_fts_repos,omitempty"`

	// Status `ok` — results follow. `empty` — workspace queried fine but
	// nothing cleared the `min_score` floor. `partial_failure` —
	// no chunks returned but at least one repo errored out during
	// the fan-out (see `failed_repos`).
	Status WorkspaceSearchResponseStatus `json:"status"`

	// Timings Where this query spent its time, in milliseconds. Returned only
	// when the request passes `timings=true` AND the query actually ran
	// a search — a workspace with no queryable project reports nothing
	// rather than a block of zeroes that would read as "instant".
	//
	// The fan-out phases report a sum AND a max, and both are needed: the
	// sum is how much work the query did across every project, the max is
	// how long it waited for the slowest one. With perfect parallelism the
	// wall time is the max; with none it is the sum; in practice it is
	// between them, and one number alone cannot say which.
	//
	// `projects_scanned` versus `projects_returned` is the ratio that says
	// how much of the work was discarded: the fan-out runs dense and BM25
	// over every project in the workspace and then thresholds the answer
	// down to the relevant ones. `projects_in_panel` is a separate,
	// smaller question — how many of those the caller was actually shown,
	// after the `top_projects` cap.
	//
	// The named phases do not sum to `wall_ms`. The remainder is the
	// workspace visibility check, assembling the projects panel, the
	// round-robin interleave and writing the response — all in memory and,
	// on the load-test fixture, ~19 ms of ~9,900 ms.
	Timings *WorkspaceSearchTimings `json:"timings,omitempty"`
}

// WorkspaceSearchResponseStatus `ok` — results follow. `empty` — workspace queried fine but
// nothing cleared the `min_score` floor. `partial_failure` —
// no chunks returned but at least one repo errored out during
// the fan-out (see `failed_repos`).
type WorkspaceSearchResponseStatus string

// WorkspaceSearchStaleFTSRepo defines model for WorkspaceSearchStaleFTSRepo.
type WorkspaceSearchStaleFTSRepo struct {
	ProjectPath string `json:"project_path"`
}

// WorkspaceSearchTimings Where this query spent its time, in milliseconds. Returned only
// when the request passes `timings=true` AND the query actually ran
// a search — a workspace with no queryable project reports nothing
// rather than a block of zeroes that would read as "instant".
//
// The fan-out phases report a sum AND a max, and both are needed: the
// sum is how much work the query did across every project, the max is
// how long it waited for the slowest one. With perfect parallelism the
// wall time is the max; with none it is the sum; in practice it is
// between them, and one number alone cannot say which.
//
// `projects_scanned` versus `projects_returned` is the ratio that says
// how much of the work was discarded: the fan-out runs dense and BM25
// over every project in the workspace and then thresholds the answer
// down to the relevant ones. `projects_in_panel` is a separate,
// smaller question — how many of those the caller was actually shown,
// after the `top_projects` cap.
//
// The named phases do not sum to `wall_ms`. The remainder is the
// workspace visibility check, assembling the projects panel, the
// round-robin interleave and writing the response — all in memory and,
// on the load-test fixture, ~19 ms of ~9,900 ms.
type WorkspaceSearchTimings struct {
	// Bm25MaxMs The slowest single project's BM25 search.
	Bm25MaxMs *int `json:"bm25_max_ms,omitempty"`

	// Bm25SumMs FTS5/BM25 search summed across projects, on the same terms as
	// dense_sum_ms.
	Bm25SumMs *int `json:"bm25_sum_ms,omitempty"`

	// DenseMaxMs The slowest single project's dense search. May belong to a
	// project whose query failed; the fan-out logs a warning of its
	// own for those.
	DenseMaxMs *int `json:"dense_max_ms,omitempty"`

	// DenseSumMs Vector-store search summed across projects, including hydration
	// of each project's winning rows, and including projects whose
	// query failed — the time was spent either way, and omitting it
	// would put the sums permanently below the wall time they explain.
	DenseSumMs *int `json:"dense_sum_ms,omitempty"`

	// EmbedMs Round-trip to the embedding provider for the query text.
	EmbedMs *int `json:"embed_ms,omitempty"`

	// FanoutMs Wall time of the parallel per-project phase.
	FanoutMs *int `json:"fanout_ms,omitempty"`

	// FuseMs Normalisation, candidacy blending and thresholding.
	FuseMs *int `json:"fuse_ms,omitempty"`

	// ProjectsInPanel Projects present in the response's `projects` array, i.e.
	// `min(projects_returned, top_projects)`.
	ProjectsInPanel *int `json:"projects_in_panel,omitempty"`

	// ProjectsReturned Projects that survived the relevance threshold — NOT the number
	// the caller was shown. Capping this at `top_projects` would peg
	// the scanned:returned ratio to a request parameter instead of
	// measuring how much of the fan-out's work was discarded.
	ProjectsReturned *int `json:"projects_returned,omitempty"`

	// ProjectsScanned Projects the fan-out searched.
	ProjectsScanned *int `json:"projects_scanned,omitempty"`

	// ResolveMs Loading the workspace's project memberships and applying the
	// per-user access filter. Separate from the rest because it is the
	// one pre-fan-out step that grows with how many projects the
	// caller can see, rather than with the workspace.
	ResolveMs *int `json:"resolve_ms,omitempty"`

	// StaleFtsMs The pre-fan-out probe for repos with no BM25 mirror.
	StaleFtsMs *int `json:"stale_fts_ms,omitempty"`

	// WallMs The whole handler, from its first line to its last.
	WallMs *int `json:"wall_ms,omitempty"`
}

